 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The full-width 2 row is the boundary. Paint the columns where
    # the colored markers at the top and bottom overlap, above it.
    barrier = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), len(grid))
    if not grid or barrier == len(grid):
        return out
    top_cols = {c for c, v in enumerate(grid[0]) if v != 0}
    bottom_cols = {c for c, v in enumerate(grid[-1]) if v != 0}
    for c in top_cols & bottom_cols:
        for r in range(1, barrier):
            out[r][c] = 4
    return out
